{
    "agents": {
        "defaults": {
            "model": {
                "fallbacks": [
                    "openai/gpt-6.1-sol"
                ],
                "primary": "anthropic/claude-opus-5-5"
            }
        }
    },
    "channels": {
        "telegram": {
            "allowFrom": [],
            "dmPolicy": "allowlist",
            "enabled": false,
            "streaming": {
                "mode": "partial",
                "preview": {
                    "commandText": "raw",
                    "toolProgress": true
                }
            }
        }
    },
    "gateway": {
        "allowRealIpFallback": false,
