                "lockoutMs": 300000,
                "maxAttempts": 10,
                "windowMs": 60000
            }
        },
        "bind": "loopback",
        "http": {
            "endpoints": {
                "chatCompletions": {
                    "enabled": false
                }
            }
        },
        "mode": "local",
        "port": 18789,
        "trustedProxies": [
            "127.0.0.1"
        ]
    },
    "plugins": {
        "entries": {
            "telegram": {
                "enabled": false
            },
            "whatsapp": {
                "enabled": false
            }
        }
    },
    "session": {
        "dmScope": "main"
    }
}
